1	/**
2	 * The evening wear confirmation — the decision, as a pure function.
3	 *
4	 * This exists because "Auto-log worn looks" was rejected twice: opening a look
5	 * is not wearing it, and `wear_logs` is the foundation of cost-per-wear,
6	 * streaks, most-worn, gathering-dust and gap analysis — i.e. of everything Pro
7	 * sells. Logging views as wears inflates all of it permanently, with no way
8	 * afterwards to tell a fabricated wear from a real one. Asking is the honest
9	 * version of the same idea, and it needs no push, so it is buildable today.
10	 *
11	 * Everything here is a value, so none of it needs a database to test.
12	 */
13	
14	/** Local hour from which the day is over enough to ask about it. */
15	export const EVENING_HOUR = 18;
16	
17	export type ViewedLook = { id: string; lookName: string; viewedAt: string };
18	
19	export type ConfirmDecision =
20	  | { ask: false }
21	  | { ask: true; outfitId: string; lookName: string };
22	
23	export function shouldAsk(args: {
24	  /** The user's LOCAL hour. Taking an hour rather than a Date is deliberate —
25	   *  a UTC hour would roll the question into the afternoon for eastern users,
26	   *  the same failure Decision 5 exists to prevent for the daily drop. */
27	  nowLocalHour: number;
28	  today: string;
29	  /** Set by BOTH answers. A No that leaves the question askable is a sheet that
30	   *  reappears until the user gives in — manufacturing the very data this
31	   *  feature exists to keep honest. */
32	  askedOn: string | null;
33	  hasWearToday: boolean;
34	  viewedToday: ViewedLook[];
35	}): ConfirmDecision {
36	  if (args.nowLocalHour < EVENING_HOUR) return { ask: false };
37	  if (args.askedOn === args.today) return { ask: false };
38	  // They already told us; asking again is noise.
39	  if (args.hasWearToday) return { ask: false };
40	  if (!args.viewedToday.length) return { ask: false };
41	
42	  // Most recent, computed here rather than trusted from the caller's ordering —
43	  // the rule is "the last thing they looked at", not "whatever the query
44	  // happened to return first". Dwell time is not tracked, so most-recent is the
45	  // honest simple choice.
46	  const latest = args.viewedToday.reduce((a, b) => (a.viewedAt >= b.viewedAt ? a : b));
47	
48	  return { ask: true, outfitId: latest.id, lookName: latest.lookName };
49	}
