11	/**
12	 * Persist a partial preferences patch.
13	 *
14	 * Merge-patch, not replace: two settings screens open at once must not have the
15	 * last save silently revert the other's toggle.
16	 *
17	 * Validation uses the STRICT schema — a bad value is rejected here rather than
18	 * repaired on every later read.
19	 */
20	export async function updatePreferences(patch: unknown): Promise<void> {
21	  const data = PreferencesSchema.partial().parse(patch);
22	
23	  const supabase = await createClient();
24	  const {
25	    data: { user },
26	  } = await supabase.auth.getUser();
27	  if (!user) throw new Error("Not signed in");
28	
29	  const { data: row } = await supabase
30	    .from("profiles")
31	    .select("preferences")
32	    .eq("id", user.id)
33	    .single();
34	
35	  const next = { ...readPreferences(row?.preferences), ...data };
36	
37	  const { error } = await supabase.from("profiles").update({ preferences: next }).eq("id", user.id);
38	  if (error) throw new Error(error.message);
39	
40	  revalidatePath("/settings");
41	  // The stylist screen reads both preferences: rain guard reaches weatherRules,
42	  // tempUnit reaches the weather strip.
43	  revalidatePath("/generate");
44	}
