110	/**
111	 * Today's looks were composed for the OLD city's weather, so a move invalidates
112	 * them. Decision 5 caches the drop; it does not make it correct for a different
113	 * climate — without this you land in Reykjavik and see outfits built for 26°C
114	 * Manila rain under a strip reading 12°C overcast.
115	 *
116	 * The rebuild is FREE, and that is not incidental: `generation_events` records
117	 * `kind` by whether a stored set already exists, so deleting the set is exactly
118	 * what makes the next call a `drop`. MONETISATION §2 — drops are never metered,
119	 * on any tier. The user changed a setting; they did not ask for a reroll.
120	 *
121	 * ⚠️ Keyed on the NEW timezone. Crossing zones can change what "today" is, and
122	 * deleting under the old key would destroy a past day's history while leaving
123	 * the row that is actually stale untouched — both intentions inverted.
124	 */
125	async function clearTodaysDrop(
126	  supabase: Awaited<ReturnType<typeof createClient>>,
127	  userId: string,
128	  timezone: string,
129	): Promise<void> {
130	  const today = localDateFor(new Date(), timezone);
131	
132	  // Styled looks carry a weather snapshot too, and are cached per
133	  // (user, item, local day) — a look styled for Manila is as wrong as a drop is.
134	  const { data: rows } = await supabase
135	    .from("outfits")
136	    .select("id")
137	    .eq("user_id", userId)
138	    .eq("generated_on", today);
139	
140	  const ids = (rows ?? []).map((r) => r.id);
141	  if (!ids.length) return;
142	
143	  await supabase.from("outfit_items").delete().in("outfit_id", ids);
144	  await supabase.from("outfits").delete().in("id", ids);
145	}
